functions.icash_save_discovery:
CREATE OR REPLACE FUNCTION public.icash_save_discovery(p_account uuid, p_operation text, p_revision uuid, p_page integer, p_result jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare c public.icash_discovery_configs; o public.icash_operation_spend; saved jsonb; row jsonb; n integer:=0; stamp timestamptz; used bigint;
begin
 select * into o from public.icash_operation_spend where operation_key=p_operation for update;
 if not found or o.account_id<>p_account or o.state<>'dispatched' then raise exception 'Dispatched acquisition required'; end if;
 select result into saved from public.icash_discovery_results where operation_key=p_operation;
 if found then if saved<>p_result then raise exception 'Discovery result conflict';end if;return jsonb_array_length(saved->'rows');end if;
 select * into c from public.icash_discovery_configs where account_id=p_account for update;
 if not found or c.revision<>p_revision or c.next_page<>p_page or c.rate_id<>o.rate_id then raise exception 'Discovery configuration changed';end if;
 if jsonb_typeof(p_result->'rows') is distinct from 'array' or jsonb_array_length(p_result->'rows')>c.per_page or octet_length(p_result::text)>524288 then raise exception 'Invalid discovery result';end if;
 used:=(p_result->>'creditsUsed')::bigint;stamp:=(p_result->>'fetchedAt')::timestamptz;
 if used is null or used<0 or stamp is null or stamp>now()+interval '1 minute' or stamp<now()-interval '1 day' or (p_result->>'peopleCredits')::bigint is distinct from 0 then raise exception 'Invalid discovery receipt';end if;
 perform public.icash_record_cost_observation('dealmachine',p_operation,'dealmachine:search:'||p_operation,used,'provider_credits');
 for row in select value from jsonb_array_elements(p_result->'rows') loop
  perform public.icash_enqueue_screening(p_account,p_operation||':'||(row->>'dm_property_id'),jsonb_build_object('propertyId',row->>'dm_property_id','propertyType','house','fetchedAt',stamp,'assignmentFeeCents',c.assignment_fee_cents,'sellerCostReserveCents',c.seller_cost_reserve_cents,'raw',jsonb_build_object('data',row)),stamp);
  n:=n+1;
 end loop;
 insert into public.icash_discovery_results(operation_key,account_id,result) values(p_operation,p_account,p_result);
 update public.icash_discovery_configs set next_page=next_page+1,exhausted=not coalesce((p_result->>'hasNextPage')::boolean,false),enabled=case when used>(p_result->>'estimatedCredits')::bigint then false else enabled end where account_id=p_account;
 return n;
end $function$

functions.icash_claim_inventory:
CREATE OR REPLACE FUNCTION public.icash_claim_inventory(p_account uuid, p_screening uuid, p_phone text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare prop text;keys text[];k text;held public.icash_inventory_claims;contact text;
begin
 select snapshot->>'propertyId' into prop from public.icash_screening_jobs where id=p_screening and account_id=p_account;
 if prop is null or prop !~ '^prop_[A-Za-z0-9]+$' then return false;end if;
 keys:=array['property:'||prop];
 if p_phone is not null then
 if p_phone !~ '^\+[1-9][0-9]{7,14}$' then return false;end if;
 contact:=encode(extensions.digest(p_phone,'sha256'),'hex');
 if exists(select 1 from public.icash_text_suppressions where phone=p_phone) or exists(select 1 from public.icash_contact_suppressions where contact_key=contact) then return false;end if;
 keys:=array_append(keys,'phone:'||contact);
 end if;
 -- All callers share deterministic lock ordering. No partial claim on a denied pair.
 for k in select x from unnest(keys) x order by x loop perform pg_advisory_xact_lock(hashtextextended(k,219));end loop;
 for k in select x from unnest(keys) x order by x loop
 select * into held from public.icash_inventory_claims where resource_key=k;
 if found and held.account_id<>p_account and (
 held.cooldown_until>now()
 or exists(select 1 from public.icash_deal_files d join public.icash_screening_jobs s on s.id=d.screening_id where d.account_id=held.account_id and d.stage in ('under_contract','buyer_selected','title_open','closing') and s.snapshot->>'propertyId'=(select snapshot->>'propertyId' from public.icash_screening_jobs where id=held.screening_id))
 or exists(select 1 from public.icash_live_callbacks where account_id=held.account_id and screening_id=held.screening_id and state in ('pending_dispatch_review','held_for_human'))
 or exists(select 1 from public.icash_live_conversations where account_id=held.account_id and screening_id=held.screening_id and state in ('waiting','review'))
 ) then return false;end if;
 end loop;
 foreach k in array keys loop
 insert into public.icash_inventory_claims(resource_key,account_id,screening_id,cooldown_until) values(k,p_account,p_screening,now()+interval '30 days')
 on conflict(resource_key) do update set account_id=excluded.account_id,screening_id=excluded.screening_id,cooldown_until=excluded.cooldown_until,updated_at=now();
 end loop;
 return true;
end $function$

functions.icash_next_acquisition:
CREATE OR REPLACE FUNCTION public.icash_next_acquisition()
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare c public.icash_discovery_configs;j uuid;t public.icash_automation_tickets;backlog integer;
begin
 perform 1 from public.icash_operating_budget where id=1 and enabled for update;
 if not found then return null;end if;
 update public.icash_automation_tickets set state='held',outcome='expired' where kind in ('contacts','discovery') and state='issued' and expires_at<=now();
 for c in select d.* from public.icash_discovery_configs d join public.icash_accounts a on a.id=d.account_id join public.icash_wallets w on w.account_id=a.id
 where d.enabled and d.auto_enabled and d.next_run_at<=now() and d.data_rights_until>now() and not a.bot_paused and w.balance_cents>w.reserved_cents
 and not exists(select 1 from public.icash_automation_tickets x where x.account_id=a.id and ((x.state='issued' and x.expires_at>now()) or (x.state='consumed' and x.created_at>now()-interval '5 minutes')))
 order by d.next_run_at,d.account_id limit 20 for update of d skip locked loop
 j:=null;
 if c.contacts_enabled and c.contact_rate_id is not null then j:=public.icash_enrichment_candidate(c.account_id);end if;
 if j is not null then
 update public.icash_discovery_configs set next_run_at=now()+interval '1 minute' where account_id=c.account_id;
 insert into public.icash_automation_tickets(account_id,kind,screening_id) values(c.account_id,'contacts',j)
 on conflict(screening_id) do update set token=gen_random_uuid()::text||gen_random_uuid()::text,state='issued',outcome=null,completed_at=null,created_at=now(),expires_at=now()+interval '2 minutes',issue_attempts=public.icash_automation_tickets.issue_attempts+1
 returning * into t;
 return jsonb_build_object('token',t.token);
 end if;
 -- Do not buy more records while the existing qualified queue needs attention.
 select count(*) into backlog from public.icash_screening_jobs s where s.account_id=c.account_id and
 (s.state in ('queued','running') or (s.state='complete' and s.result->'financialCheck'->>'status'='eligible' and s.completed_at>now()-interval '7 days'
 and not exists(select 1 from public.icash_live_conversations v where v.account_id=s.account_id and v.screening_id=s.id and v.state='complete')
 and not exists(select 1 from public.icash_deal_files d where d.account_id=s.account_id and d.screening_id=s.id)));
 update public.icash_discovery_configs set next_run_at=now()+make_interval(secs=>interval_seconds) where account_id=c.account_id;
 if c.exhausted or backlog>=c.max_open_prospects then continue;end if;
 insert into public.icash_automation_tickets(account_id,kind) values(c.account_id,'discovery') returning * into t;
 return jsonb_build_object('token',t.token);
 end loop;
 return null;
end $function$

functions.icash_claim_market_research:
CREATE OR REPLACE FUNCTION public.icash_claim_market_research(p_account uuid, p_job uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare j public.icash_market_research_jobs;n integer;
begin
 select * into j from public.icash_market_research_jobs where id=p_job and account_id=p_account for update;
 if not found or j.state<>'issued' or j.attempts>=3 or not exists(select 1 from public.icash_market_research_scopes s where s.id=j.scope_id and s.account_id=p_account and s.enabled) then return null;end if;
 n:=case when j.kind='locations' then 1 else 3 end;
 insert into public.icash_market_research_usage(day,requests_reserved) values((now() at time zone 'UTC')::date,n)
 on conflict(day) do update set requests_reserved=public.icash_market_research_usage.requests_reserved+n
 where public.icash_market_research_usage.requests_reserved+n<=50;
 if not found then return null;end if;
 update public.icash_market_research_jobs set state='running',attempts=attempts+1,updated_at=now(),next_attempt_at=now()+interval '15 minutes' where id=j.id;
 return jsonb_build_object('id',j.id,'kind',j.kind,'city',j.city,'query',coalesce((select scope.location_query from public.icash_market_research_scopes scope where scope.id=j.scope_id),j.city),'state',j.state_code,'zip',j.zip,'page',j.page);
end $function$

functions.icash_assign_seller_lead_for:
CREATE OR REPLACE FUNCTION public.icash_assign_seller_lead_for(p_lead uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare l public.icash_seller_intakes;a record;parts jsonb;total bigint;charge bigint;rate uuid;op text;screen uuid;evidence text;manifest jsonb;city_name text;state_code text;match_count integer;
begin
 -- Consistent lock order with all other paid operations.
 perform 1 from public.icash_operating_budget where id=1 for update;
 perform 1 from public.icash_seller_controls where id=1 and enabled for share;if not found then return null;end if;
 select * into l from public.icash_seller_intakes where state in ('qualified','assigned') and (p_lead is null or id=p_lead) and next_assignment_at<=now()
 and (select count(*) from public.icash_seller_matches m where m.lead_id=icash_seller_intakes.id)<3
 and (select public.icash_seller_assignment_due(count(*)::integer,min(m.assigned_at),max(m.assigned_at)) from public.icash_seller_matches m where m.lead_id=icash_seller_intakes.id)<=now()
 and not exists(select 1 from public.icash_text_suppressions s where s.phone=icash_seller_intakes.phone)
 and not exists(select 1 from public.icash_seller_matches sm join public.icash_live_conversations c on c.account_id=sm.account_id and c.screening_id=sm.screening_id join public.icash_contact_suppressions s on s.account_id=c.account_id and s.contact_key=c.contact_key where sm.lead_id=icash_seller_intakes.id)
 and not exists(select 1 from public.icash_seller_matches sm join public.icash_deal_files d on d.account_id=sm.account_id and d.screening_id=sm.screening_id join public.icash_signing_envelopes e on e.account_id=d.account_id and e.deal_id=d.id and e.kind='purchase' and not e.test_mode and e.state='completed' where sm.lead_id=icash_seller_intakes.id)

 and exists(select 1 from public.icash_accounts ac where ac.billing_model='daily' and not ac.bot_paused and not exists(select 1 from public.icash_seller_matches m where m.lead_id=icash_seller_intakes.id and m.account_id=ac.id))
 order by next_assignment_at,created_at,id limit 1 for update skip locked;
 if not found then return null;end if;
 city_name:=lower(trim(l.property->>'city'));state_code:=upper(l.property->>'state');
 if l.data_rights_until is null or l.data_rights_until<=now() or not exists(select 1 from public.icash_seller_controls where id=1 and enabled and data_rights_until>now() and length(coalesce(review_ref,''))>=10) then
 update public.icash_seller_intakes set state='review',hold_reason='Current data-use configuration required' where id=l.id;return jsonb_build_object('status','review');end if;
 if l.checked_at is null or l.checked_at<now()-interval '8 days' then
  update public.icash_seller_intakes set state='review',hold_reason='Shared research window ended' where id=l.id;
  return jsonb_build_object('status','research_window_ended');
 end if;
 parts:=coalesce(l.customer_costs,l.lookup_costs||jsonb_build_object('acquisition',0));
 if parts is null or jsonb_typeof(parts)<>'object' or nullif(l.lookup_cost_basis,'') is null then return jsonb_build_object('status','research_cost_required');end if;select sum(value::numeric)::bigint into total from jsonb_each_text(parts);charge:=ceil(total::numeric*3/10000);
 if charge<=0 then raise exception 'Positive cost-based lead price required';end if;
 evidence:=coalesce(l.customer_cost_basis,'ESTIMATE: recorded property research and operating allocations; advertising tracked separately; '||l.lookup_cost_basis);
 select count(*) into match_count from public.icash_seller_matches where lead_id=l.id;
 -- Weighted distribution at the same recorded cost-based price;
 -- eligibility remains bounded by wallet AND rolling daily usage.
 for a in select candidate.* from (select ac.id,least(w.balance_cents-w.reserved_cents,ac.daily_limit_cents-w.reserved_cents-coalesce((select sum(-delta_cents) from public.icash_credit_ledger where account_id=ac.id and kind='usage' and created_at>now()-interval '24 hours'),0)) capacity
 from public.icash_accounts ac join public.icash_wallets w on w.account_id=ac.id
 join public.icash_bot_setups bs on bs.account_id=ac.id
 where ac.billing_model='daily' and not ac.bot_paused and not exists(select 1 from public.icash_seller_matches m where m.lead_id=l.id and m.account_id=ac.id) and exists(select 1 from public.icash_daily_plans p where p.account_id=ac.id and p.state='active' and p.mode='live' and p.consent_version like 'daily-2026-10-04.1%')
 and (bs.profile->>'marketMode'='nationwide' or lower(trim(bs.profile->>'market')) in (city_name,city_name||', '||lower(state_code),l.property->>'zip'))
 and not exists(select 1 from public.icash_billing_reviews where account_id=ac.id and resolved_at is null)
 ) candidate where capacity>=charge
 -- Larger available budgets receive more opportunities; a square-root weight
 -- keeps smaller funded accounts competitive. First access rotates separately.
 order by
 case when exists(select 1 from public.icash_seller_matches m where m.account_id=candidate.id and m.assigned_at>now()-interval '24 hours') then 1 else 0 end,
 (case when match_count=0 then (select count(*) from public.icash_seller_intakes i where i.assigned_account=candidate.id and i.assigned_at>now()-interval '7 days') else (select count(*) from public.icash_seller_matches m where m.account_id=candidate.id and m.assigned_at>now()-interval '7 days') end + 1)
 /sqrt(greatest(candidate.capacity,charge)::numeric/charge)
 / (1+least(7,greatest(0,extract(epoch from(now()-coalesce((select max(m.assigned_at) from public.icash_seller_matches m where m.account_id=candidate.id),now()-interval '7 days')))/86400))),
 (select count(*) from public.icash_seller_matches m where m.account_id=candidate.id and m.assigned_at>now()-interval '7 days'),
 capacity desc,candidate.id limit 50 loop
  if a.capacity<charge then continue;end if;
  op:='seller-lead:'||l.id||':'||a.id;
  begin
   insert into public.icash_operation_rates(operation,version,charge_cents,costs_micros,buffer_bps,evidence_ref,verified_at,expires_at,enabled)
   values('seller_lead',op,charge,parts,0,evidence,now(),least(now()+interval '24 hours',l.checked_at+interval '8 days',l.data_rights_until),true) returning id into rate;
   perform public.icash_reserve_operation(a.id,op,rate,l.data_rights_until,l.checked_at,true);
   if not public.icash_claim_operation(op) then raise exception 'Lead reservation held';end if;
   select jsonb_object_agg(key,jsonb_build_object('amountMicros',value,'evidenceRef',evidence)) into manifest from jsonb_each(parts);
   perform public.icash_settle_complete_costs(op,charge,manifest,evidence);
   update public.icash_operation_spend set cost_basis='estimated' where operation_key=op;
   insert into public.icash_screening_jobs(account_id,event_key,snapshot,state,result,completed_at)
   values(a.id,op,jsonb_build_object('propertyId',l.property->>'id','propertyType','house','fetchedAt',l.property->>'fetchedAt','raw',l.property->'raw','sellerRequest',jsonb_build_object('id',l.id,'ownerName',l.name,'phone',l.phone,'aiConsented',l.ai_consented,'consentVersion',l.consent_version,'consentText',l.consent_text,'consentScope',l.contact_consent_scope,'email',l.email,'emailConsented',l.email_consented,'shared',true,'maximumBuyers',3)), 'complete',l.result,l.checked_at) returning id into screen;
   insert into public.icash_seller_matches(lead_id,account_id,screening_id,operation_key,charge_cents) values(l.id,a.id,screen,op,charge);
   -- One immediate user, second after 24 hours, third after 72 hours.
   -- Cap at three distinct users. This never simulates buyers or contact.
   update public.icash_seller_intakes set customer_costs=parts,customer_cost_basis=evidence,state='assigned',assigned_account=coalesce(assigned_account,a.id),screening_id=coalesce(screening_id,screen),operation_key=coalesce(operation_key,op),assigned_at=coalesce(assigned_at,now()),
    next_assignment_at=public.icash_seller_assignment_due(match_count+1,coalesce(assigned_at,now()),now()),hold_reason=null where id=l.id;
   return jsonb_build_object('status','assigned','leadId',l.id,'accountId',a.id,'chargeCents',charge);
  exception when others then
   -- The subtransaction rolls back rate, reservation, charge and assignment together.
   null;
  end;
 end loop;
 update public.icash_seller_intakes set next_assignment_at=now()+interval '15 minutes',hold_reason='Waiting for a funded bot whose market and daily limit fit this lead' where id=l.id;
 return jsonb_build_object('status','waiting_for_budget');
end $function$

functions.icash_claim_owner_enrichment:
CREATE OR REPLACE FUNCTION public.icash_claim_owner_enrichment(p_account uuid, p_screening uuid, p_operation text, p_snapshot jsonb, p_rate uuid, p_credit_cap integer, p_unit_cost_micros bigint, p_quoted_data_cost_micros bigint, p_rights_until timestamp with time zone)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
 o public.icash_operation_spend;
 s public.icash_screening_jobs;
 c public.icash_discovery_configs;
 r public.icash_operation_rates;
 prop text;manual_hold boolean;fetched timestamptz;checked_at timestamptz;
begin
 if p_account is null or p_screening is null or p_operation is distinct from 'owners:'||p_account||':'||p_screening
  or jsonb_typeof(p_snapshot) is distinct from 'object' or p_rate is null
  or p_credit_cap is null or p_credit_cap not between 1 and 25
  or p_unit_cost_micros is null or p_unit_cost_micros not between 1 and 9007199254740991
  or p_quoted_data_cost_micros is null or p_quoted_data_cost_micros not between 1 and 9007199254740991
  or p_credit_cap::numeric*p_unit_cost_micros>p_quoted_data_cost_micros or p_rights_until is null then return false;end if;
 -- Match the underlying claim's budget -> operation -> account order. Existing
 -- takeover paths lock the account (and current wrappers lock budget first).
 perform 1 from public.icash_operating_budget where id=1 for update;
 if not found then return false;end if;
 select * into o from public.icash_operation_spend where operation_key=p_operation for update;
 if not found or o.account_id is distinct from p_account or o.rate_id is distinct from p_rate or o.state<>'reserved' or o.permission_until is distinct from p_rights_until then return false;end if;
 perform 1 from public.icash_accounts where id=p_account and not bot_paused for update;
 if not found then return false;end if;
 select * into s from public.icash_screening_jobs where id=p_screening and account_id=p_account for share;
 if not found or s.state<>'complete' or s.snapshot is distinct from p_snapshot or s.result->'financialCheck'->>'status' is distinct from 'eligible' then return false;end if;
 prop:=s.snapshot->>'propertyId';
 if prop is null or prop !~ '^prop_[0-9]{1,20}$' or s.snapshot->'raw'->'data'->>'dm_property_id' is distinct from prop or s.snapshot->>'propertyType' is distinct from 'house' then return false;end if;
 -- Inventory rotation can already hold config before its scheduler takes budget.
 -- Fail closed instead of waiting for that row while this claim holds budget.
 begin
  select * into c from public.icash_discovery_configs where account_id=p_account for share nowait;
 exception when lock_not_available then return false;end;
 if not found or not c.enabled or not c.contacts_enabled or c.contact_rate_id is distinct from p_rate
  or c.contact_credit_cap is distinct from p_credit_cap or c.property_credit_micros is distinct from p_unit_cost_micros
  or c.data_rights_until is distinct from p_rights_until then return false;end if;
 select * into r from public.icash_operation_rates where id=p_rate for share;
 if not found or not r.enabled or r.operation<>'owner_enrichment'
  or jsonb_typeof(r.costs_micros->'dealmachine') is distinct from 'number'
  or (r.costs_micros->>'dealmachine')::numeric is distinct from p_quoted_data_cost_micros::numeric then return false;end if;
 -- A locked row must exist even for a property's first lookup. Do not change an
 -- existing manual choice. This also serializes direct property-control upserts.
 insert into public.icash_property_controls(account_id,property_id,manual) values(p_account,prop,false) on conflict do nothing;
 select manual into manual_hold from public.icash_property_controls where account_id=p_account and property_id=prop for update;
 if not found or manual_hold then return false;end if;
 begin fetched:=(s.snapshot->>'fetchedAt')::timestamptz;
 exception when invalid_datetime_format or datetime_field_overflow then return false;end;
 -- Use wall clock after waiting for all locks, rather than transaction-start time.
 checked_at:=clock_timestamp();
 if fetched is null or fetched<checked_at-interval '24 hours' or fetched>checked_at
  or s.completed_at is null or s.completed_at<checked_at-interval '24 hours' or s.completed_at>checked_at
  or c.data_rights_until<=checked_at or r.expires_at<=checked_at or r.verified_at>checked_at
  or o.permission_until<=checked_at then return false;end if;
 -- No weakened or copied billing implementation: activation, pause, funds, rate,
 -- reservation state and exactly-once checks remain in the existing dispatcher.
 return public.icash_claim_operation(p_operation);
end $function$

functions.icash_claim_seller_lookup_for:
CREATE OR REPLACE FUNCTION public.icash_claim_seller_lookup_for(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare c public.icash_seller_controls;l public.icash_seller_intakes;r public.icash_operation_rates;u public.icash_data_cost_settings;parts jsonb;cap bigint;token uuid:=gen_random_uuid();
begin
 select * into c from public.icash_seller_controls where id=1 for update;
 if not c.enabled or c.data_rights_until is null or c.data_rights_until<=now() or length(coalesce(c.review_ref,''))<10 then return null;end if;
 -- An ambiguous lookup is held permanently until an operator reconciles it.
 update public.icash_seller_intakes set state='review',hold_reason='Lookup outcome unknown; do not repeat automatically' where state='checking' and claimed_at<now()-interval '2 minutes';
 select * into r from public.icash_operation_rates where operation='property_search' and enabled and verified_at<=now() and expires_at>now() order by verified_at desc,id limit 1;
 select * into u from public.icash_data_cost_settings where provider='dealmachine';
 if r.id is null or u.credit_micros is null then return null;end if;
 parts:=r.costs_micros||jsonb_build_object('dealmachine',u.credit_micros,'acquisition',0);
 select sum(value::numeric)::bigint into cap from jsonb_each_text(parts);
 if cap<=0 or c.lookup_used_micros+c.lookup_reserved_micros+cap>c.lookup_allowance_micros then return null;end if;
 select * into l from public.icash_seller_intakes where state='received' and (p_id is null or id=p_id) order by created_at,id limit 1 for update skip locked;
 if not found then return null;end if;
 update public.icash_seller_controls set lookup_reserved_micros=lookup_reserved_micros+cap where id=1;
 update public.icash_seller_intakes set state='checking',claim_token=token,claimed_at=now(),lookup_costs=parts,lookup_cap_micros=cap,lookup_cost_basis=u.cost_basis||'; '||u.source_ref||'; non-data allocations: '||r.evidence_ref,data_rights_until=c.data_rights_until where id=l.id;
 return jsonb_build_object('id',l.id,'token',token,'address',l.address,'assignmentFeeCents',c.assignment_fee_cents,'sellerCostReserveCents',c.seller_cost_reserve_cents);
end $function$

functions.icash_rotate_inventory_market:
CREATE OR REPLACE FUNCTION public.icash_rotate_inventory_market(p_account uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare c public.icash_discovery_configs;m public.icash_inventory_markets;
begin
 select * into c from public.icash_discovery_configs where account_id=p_account for update;
 if not found or not c.exhausted or not c.enabled or not c.auto_enabled or c.data_rights_until<=now() then return false;end if;
 if not exists(select 1 from public.icash_accounts a join public.icash_wallets w on w.account_id=a.id where a.id=p_account and not a.bot_paused and w.balance_cents>w.reserved_cents) then return false;end if;
 select * into m from public.icash_inventory_markets where account_id=p_account and eligible_until>now() and next_scan_at<=now() order by priority,zip for update skip locked limit 1;
 if not found then return false;end if;
 update public.icash_discovery_configs set zip=m.zip,next_page=1,revision=gen_random_uuid(),exhausted=false where account_id=p_account;
 update public.icash_inventory_markets set next_scan_at=now()+interval '30 days' where account_id=p_account and zip=m.zip;
 return true;
end $function$

functions.icash_provision_before_voice_template:
CREATE OR REPLACE FUNCTION public.icash_provision_before_voice_template(p_account uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare search public.icash_operation_rates;contacts public.icash_operation_rates;buyers public.icash_operation_rates;profile jsonb;chosen text;requested text;unit bigint;until_at timestamptz;existing public.icash_discovery_configs;
begin
 perform pg_advisory_xact_lock(hashtextextended(p_account::text,7301));
 if not exists(select 1 from public.icash_funding_orders where account_id=p_account and mode='live' and state='paid' and credited_at is not null) then return jsonb_build_object('status','funding_required');end if;
 select * into search from public.icash_operation_rates where operation='property_search' and enabled and expires_at>now() order by verified_at desc limit 1;
 select * into contacts from public.icash_operation_rates where operation='owner_enrichment' and enabled and expires_at>now() order by verified_at desc limit 1;
 select * into buyers from public.icash_operation_rates where operation='buyer_discovery' and enabled and expires_at>now() order by verified_at desc limit 1;
 select credit_micros into unit from public.icash_data_cost_settings where provider='dealmachine';
 if search.id is null or contacts.id is null or buyers.id is null or unit is null then return jsonb_build_object('status','data_rates_required');end if;
 perform public.icash_claim_bot_setup(p_account);
 select s.profile into profile from public.icash_bot_setups s where account_id=p_account;
 select * into existing from public.icash_discovery_configs where account_id=p_account;
 chosen:=existing.zip;
 requested:=case when profile->>'marketMode'='city' and trim(profile->>'market') ~ '^[0-9]{5}$' then trim(profile->>'market') end;
 if requested is not null then
  -- Never switch an existing operator configuration or an in-flight search implicitly.
  if chosen is not null and chosen<>requested then return jsonb_build_object('status','existing_market_configuration_preserved');end if;
  chosen:=requested;
 end if;
 if chosen is null then
 select m.zip into chosen from public.icash_market_shortlist m
 where (coalesce(profile->>'marketMode','nationwide')='nationwide' or lower(trim(profile->>'market')) in (lower(m.city),lower(m.city||', '||m.state),m.zip)) and m.state ~ '^[A-Z]{2}$'
 order by (select count(*) from public.icash_discovery_configs c where c.zip=m.zip),m.priority limit 1;
 end if;
 if chosen is null or not public.icash_research_zip_known(chosen) then return jsonb_build_object('status','market_configuration_required');end if;
 until_at:=least(search.expires_at,contacts.expires_at,buyers.expires_at);
 insert into public.icash_discovery_configs(account_id,enabled,zip,rate_id,property_credit_micros,data_rights_until,seller_cost_reserve_cents,per_page,auto_enabled,contacts_enabled,contact_rate_id,contact_credit_cap)
 values(p_account,true,chosen,search.id,unit,until_at,0,5,true,true,contacts.id,least(25,greatest(1,(contacts.costs_micros->>'dealmachine')::bigint/unit))) on conflict(account_id) do nothing;
 -- Existing configurations and operator pauses are never overwritten on a refresh.
 insert into public.icash_buyer_search_configs(account_id,enabled,rate_id,unit_cost_micros,rights_until,zip,since,per_page,max_pages)
 values(p_account,true,buyers.id,unit,until_at,chosen,(current_date-365),10,5) on conflict(account_id) do nothing;
 insert into public.icash_inventory_markets(account_id,zip,priority,eligible_until)
 select p_account,m.zip,m.priority,until_at from public.icash_market_shortlist m
 where (coalesce(profile->>'marketMode','nationwide')='nationwide' or m.zip=chosen) and m.state ~ '^[A-Z]{2}$'
 on conflict(account_id,zip) do nothing;
 -- Explicit ZIP requests outside the default shortlist receive only that one ZIP.
 if requested is not null then
  insert into public.icash_inventory_markets(account_id,zip,priority,eligible_until) values(p_account,chosen,100,until_at) on conflict(account_id,zip) do nothing;
 end if;
 return jsonb_build_object('status','configured','zip',chosen,'costBasis','estimated','expiresAt',until_at);
end $function$

functions.icash_reserve_and_claim_property_discove:
CREATE OR REPLACE FUNCTION public.icash_reserve_and_claim_property_discovery(p_account uuid, p_zip text, p_revision uuid, p_page integer, p_per_page integer, p_rate uuid, p_unit bigint, p_permission_until timestamp with time zone, p_setup_revision integer, p_market_mode text, p_market text)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare c public.icash_discovery_configs;s public.icash_bot_setups;g public.icash_property_zip_geographies;
 r public.icash_operation_rates;o public.icash_operation_spend;known_shortlist boolean:=false;op text;checked timestamptz;
begin
 -- Keep the existing global financial lock order before narrower account/config locks.
 perform 1 from public.icash_operating_budget where id=1 for update;
 perform 1 from public.icash_accounts where id=p_account for update;
 if not found then return false;end if;
 select * into c from public.icash_discovery_configs where account_id=p_account for update;
 if not found then return false;end if;
 select * into s from public.icash_bot_setups where account_id=p_account for share;
 select * into r from public.icash_operation_rates where id=p_rate for share;
 perform 1 from public.icash_market_shortlist where zip=p_zip and state ~ '^[A-Z]{2}$' for share;
 known_shortlist:=found;
 if not known_shortlist then select * into g from public.icash_property_zip_geographies where zip=p_zip for share;end if;
 checked:=clock_timestamp();
 if not c.enabled or not c.auto_enabled or c.exhausted or c.data_rights_until<=checked
 or row(c.zip,c.revision,c.next_page,c.per_page,c.rate_id,c.property_credit_micros,c.data_rights_until)
 is distinct from row(p_zip,p_revision,p_page,p_per_page,p_rate,p_unit,p_permission_until)
 or row(s.revision,s.profile->>'marketMode',s.profile->>'market') is distinct from row(p_setup_revision,p_market_mode,p_market)
 or (s.profile->>'marketMode'='city' and trim(s.profile->>'market') ~ '^[0-9]{5}$' and trim(s.profile->>'market')<>p_zip)
 or r.operation is distinct from 'property_search' or not coalesce(r.enabled,false) or r.expires_at<=checked
 or p_page<1 or p_per_page not between 1 and 10 or p_unit<1
 or (not known_shortlist and (g.state_code is null or g.property_count is null or g.property_count<=0 or g.checked_at is null or g.checked_at>checked or g.expires_at is null or g.expires_at<=checked)) then return false;end if;
 op:='discovery:'||p_account||':'||p_revision||':'||p_page;
 select * into o from public.icash_operation_spend where operation_key=op for update;
 if found and (o.state<>'reserved' or row(o.account_id,o.rate_id,o.permission_until) is distinct from row(p_account,p_rate,p_permission_until)) then return false;end if;
 perform public.icash_reserve_operation(p_account,op,p_rate,p_permission_until,null,false);
 -- now() is the transaction start, so use wall-clock time again after any downstream wait.
 checked:=clock_timestamp();
 if c.data_rights_until<=checked or r.expires_at<=checked or (not known_shortlist and g.expires_at<=checked) then
  raise exception 'Property discovery scope expired before claim';
 end if;
 if not public.icash_claim_operation(op) then raise exception 'Property discovery claim held';end if;
 checked:=clock_timestamp();
 if c.data_rights_until<=checked or r.expires_at<=checked or (not known_shortlist and g.expires_at<=checked) then
  raise exception 'Property discovery scope expired during claim';
 end if;
 return true;
end $function$
